import 'dart:typed_data';
import 'dart:convert';

/// Ultra-sharp Lanczos-filtered HD NCS Logo Icon for Naviera Cruz del Sur.

const String ncsCourseLogoHDBase64 = '';
const String ncsCourseLogoOrigBase64 = '';

Uint8List? getCourseImageBytes(int courseId) {
  try {
    return base64Decode(ncsCourseLogoHDBase64);
  } catch (_) {
    return null;
  }
}
